// Writes the Combine Files smoke-test inputs into a directory: a 3-page text
// PDF, a 900x600 PNG, and a 2-page uncompressed RGB TIFF. All generated by
// hand (no dependencies) so CI can run it on a bare runner.
//
// Usage: node scripts/make-combine-smoke-samples.cjs <dir>
// Expected combined output (see check-combined-pdf.mjs): the three PDF pages
// at 612x792, the PNG on a 792x528 landscape page, the TIFF pages at 609x792.
const fs = require("fs");
const path = require("path");
const zlib = require("zlib");

const dir = process.argv[2];
if (!dir) {
  console.error("usage: make-combine-smoke-samples.cjs <dir>");
  process.exit(2);
}
fs.mkdirSync(dir, { recursive: true });

// --- PDF -----------------------------------------------------------------
function pdf(pagesText) {
  const objs = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    null,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ];
  const kids = [];
  for (const t of pagesText) {
    const content = `BT /F1 36 Tf 72 692 Td (${t}) Tj ET`;
    const c = objs.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
    const p = objs.push(
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents ${c} 0 R /Resources << /Font << /F1 3 0 R >> >> >>`
    );
    kids.push(`${p} 0 R`);
  }
  objs[1] = `<< /Type /Pages /Kids [${kids.join(" ")}] /Count ${kids.length} >>`;
  let out = "%PDF-1.4\n";
  const offsets = [];
  objs.forEach((body, i) => {
    offsets.push(out.length);
    out += `${i + 1} 0 obj\n${body}\nendobj\n`;
  });
  const xref = out.length;
  out +=
    `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n` +
    offsets.map((o) => String(o).padStart(10, "0") + " 00000 n \n").join("") +
    `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out, "latin1");
}

// --- PNG (8-bit RGB, filter 0, one IDAT) ----------------------------------
function crc32(buf) {
  let crc = 0xffffffff;
  for (let n = 0; n < buf.length; n++) {
    let c = (crc ^ buf[n]) & 0xff;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xffffffff) >>> 0;
}
function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}
function png(w, h, px) {
  const raw = Buffer.alloc((w * 3 + 1) * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const [r, g, b] = px(x, y);
      const o = y * (w * 3 + 1) + 1 + x * 3;
      raw[o] = r;
      raw[o + 1] = g;
      raw[o + 2] = b;
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // truecolor
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", ihdr),
    chunk("IDAT", zlib.deflateSync(raw)),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

// --- TIFF (little endian, uncompressed RGB, one strip per page) ------------
function tiff(pages) {
  const layout = [];
  let cursor = 8;
  const blobs = pages.map(({ w, h, px }) => {
    const data = Buffer.alloc(w * h * 3);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const [r, g, b] = px(x, y);
        const o = (y * w + x) * 3;
        data[o] = r;
        data[o + 1] = g;
        data[o + 2] = b;
      }
    }
    return { w, h, data };
  });
  const TAGS = 10;
  for (const b of blobs) {
    const bpsOff = cursor; // BitsPerSample array (3 shorts) lives before the IFD
    const ifdOff = bpsOff + 6;
    const dataOff = ifdOff + 2 + TAGS * 12 + 4;
    layout.push({ bpsOff, ifdOff, dataOff });
    cursor = dataOff + b.data.length;
  }
  const parts = [];
  const head = Buffer.from([0x49, 0x49, 42, 0, 0, 0, 0, 0]);
  head.writeUInt32LE(layout[0].ifdOff, 4);
  parts.push(head);
  blobs.forEach((b, i) => {
    const { bpsOff, ifdOff, dataOff } = layout[i];
    const entries = [
      [256, 4, 1, b.w], // ImageWidth
      [257, 4, 1, b.h], // ImageLength
      [258, 3, 3, bpsOff], // BitsPerSample -> offset
      [259, 3, 1, 1], // Compression: none
      [262, 3, 1, 2], // Photometric: RGB
      [273, 4, 1, dataOff], // StripOffsets
      [277, 3, 1, 3], // SamplesPerPixel
      [278, 4, 1, b.h], // RowsPerStrip
      [279, 4, 1, b.data.length], // StripByteCounts
      [284, 3, 1, 1], // PlanarConfiguration: chunky
    ];
    const ifd = Buffer.alloc(2 + entries.length * 12 + 4);
    ifd.writeUInt16LE(entries.length, 0);
    entries.forEach(([tag, type, count, value], k) => {
      const o = 2 + k * 12;
      ifd.writeUInt16LE(tag, o);
      ifd.writeUInt16LE(type, o + 2);
      ifd.writeUInt32LE(count, o + 4);
      if (type === 3 && count === 1) ifd.writeUInt16LE(value, o + 8);
      else ifd.writeUInt32LE(value, o + 8);
    });
    ifd.writeUInt32LE(i + 1 < blobs.length ? layout[i + 1].ifdOff : 0, 2 + entries.length * 12);
    parts.push(Buffer.from([8, 0, 8, 0, 8, 0]), ifd, b.data);
  });
  return Buffer.concat(parts);
}

fs.writeFileSync(path.join(dir, "Alpha report.pdf"), pdf(["Alpha page 1", "Alpha page 2", "Alpha page 3"]));
fs.writeFileSync(
  path.join(dir, "Photo landscape.png"),
  png(900, 600, (x, y) =>
    x > 300 && x < 600 && y > 200 && y < 400
      ? [220, 30, 30]
      : [Math.round((x / 900) * 255), Math.round((y / 600) * 255), 160]
  )
);
fs.writeFileSync(
  path.join(dir, "Scan two pages.tif"),
  tiff([
    { w: 400, h: 520, px: (x, y) => (y % 40 < 6 && x > 40 && x < 360 ? [30, 30, 30] : [250, 250, 245]) },
    { w: 400, h: 520, px: (x, y) => ((x - 200) ** 2 + (y - 260) ** 2 < 120 ** 2 ? [20, 90, 200] : [245, 245, 250]) },
  ])
);
for (const f of fs.readdirSync(dir)) {
  console.log(`${f}: ${fs.statSync(path.join(dir, f)).size} bytes`);
}
